/* Lot 111: wf_css_math_box with mixed min()/max()/clamp() nested or in an arithmetic (generated by scripts/lot111_gen.py; expectations from scripts/lot111_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssmath.h"

static char g_o[160];

/* "r px out" of wf_css_math_box at 640 x 480 */
static const char *mb(const char *s, int em, int rem) {
    char out[64];
    int px = -7, r = wf_css_math_box(s, 640, 480, em, rem, &px, out, (int)sizeof(out));
    snprintf(g_o, sizeof(g_o), "%d %d %s", r, px, out);
    return g_o;
}

static void test_l111_mix_0(void) {
    TEST_ASSERT_EQUAL_STRING("2 0 calc(81% + 91px)", mb("calc(81% + 91px)", 16000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 min(max(25%, 10px), 5%)", mb("calc(min(max(100%, 16ex), 19%) * 0.25)", 8000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 max(calc(34% + 192px), 223px)", mb("calc(max(34%, calc(min(13vh, 139px, 4.25em) * 0.5)) + min(25.2lh, 12em))", 16000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 min(84%, max(19%, calc(98% - 119px)))", mb("min(84%, max(19%, calc(98% - 119px)))", 32000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 max(calc(43% + 43px), min(-48%, calc(-91% + 198px)))", mb("max(calc(43% + 43px), calc(min(43%, 198px) - 91%))", 16000, 20000));
    TEST_ASSERT_EQUAL_STRING("2 0 calc(85% - 290px)", mb("calc(85% - 36.25ch)", 16000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 max(43px, calc(20% - 3px), 17%, 562px)", mb("max(calc(max(173px, calc(3 * (27.25% - 3.25pt))) / 4), 17%, 35.125rem)", 16000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 min(clamp(calc(216% + 416px), calc(19% + 273px), 595px), 84%)", mb("min(calc(clamp(calc(54% + 104px), calc(4.75% + 14.2vh), 31vh) * 4), 84%)", 20000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 max(clamp(28%, 94%, calc(8% + 80px)), 68%)", mb("calc(max(calc(clamp(10%, 43%, 4ch) / 0.5), 60%) + calc(32% * 0.25))", 20000, 20000));
    TEST_ASSERT_EQUAL_STRING("2 0 max(252%, 228%, 19px)", mb("calc(max(63%, 57%, 1vh) * 4)", 8000, 20000));
    TEST_ASSERT_EQUAL_STRING("2 0 calc(66% - 184px)", mb("calc(66% - 184px)", 10000, 20000));
    TEST_ASSERT_EQUAL_STRING("2 0 min(calc(198% - 28px), 54%, 106px)", mb("min(calc(min(calc(99% - 14px), 27%) / 0.5), 22vh)", 16000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 min(52%, clamp(1445px, -263px, calc(-96% + 261px)), 110px)", mb("min(max(52%, 23%), calc(clamp(54em, 20.2px, calc(34pc - 96%)) - 59vh), 23vh)", 32000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 min(106px, 158%)", mb("calc(min(53px, 79%) / 0.5)", 20000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 min(calc(-22% + 244px), calc(-70% + 216px), calc(-60% + 144px))", mb("calc(min(calc(48% + 100px), calc(min(287px, 41%) * 0.25)) - calc(2 * (35% - 4.5rem)))", 32000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 clamp(53%, 364px, min(800px, 212%))", mb("clamp(calc(53% + 0px), 18.2rem, calc(min(25ch, 53%) * 4))", 16000, 20000));
    TEST_ASSERT_EQUAL_STRING("2 0 clamp(max(11%, 105px), calc(88% - 137px), 151px)", mb("clamp(max(11%, 105px), calc(88% - 137px), 151px)", 8000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 calc(47% + 82px)", mb("calc(47% + 5.125em)", 16000, 20000));
    TEST_ASSERT_EQUAL_STRING("2 0 min(186px, 123px, calc(28% + 3px), calc(43% + 3px))", mb("min(186px, calc(min(24ch, 28%, 43%) + 3px))", 10000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 min(72px, calc(1% + 0px))", mb("calc(min(144px, calc((16% + 5.2px) / 8)) * 0.5)", 20000, 20000));
}

